import os,re
mods={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if fn.endswith('.lean'):
            p=os.path.join(dp,fn); mods[p[:-5].replace('/','.')]=p
imp={}; hasM={}
for n,p in mods.items():
    ds=[]; m_any=False
    for line in open(p,errors='replace'):
        m=re.match(r'^import\s+([A-Za-z0-9_.]+)',line)
        if m:
            d=m.group(1)
            if d.startswith('Mathlib'): m_any=True
            elif d.startswith('AlgebraicJacobian'): ds.append(d)
    imp[n]=ds; hasM[n]=m_any
noM=[n for n in mods if not hasM[n]]
print('modules with NO Mathlib import of their own:',len(noM))
# those whose deps include an already-converted (narrow) module
converted=set()
for n,p in mods.items():
    t=open(p,errors='replace').read()
    if re.search(r'^import Mathlib\.',t,re.M) and not re.search(r'^import Mathlib$',t,re.M):
        converted.add(n)
print('narrow (precise-import) modules:',len(converted))
risk=[n for n in noM if any(d in converted for d in imp[n])]
print('AT RISK (no own Mathlib import, imports a narrowed module):',len(risk))
for r in risk: print('   ',r,'<-',[d for d in imp[r] if d in converted])
